{"sql":"SELECT t.TrackId, t.Name, pt.cnt
FROM (
  SELECT TrackId, COUNT(*) AS cnt
  FROM PlaylistTrack
  GROUP BY TrackId
) pt
JOIN Track t USING (TrackId)
WHERE pt.cnt = (
  SELECT MAX(c) FROM (
    SELECT COUNT(*) AS c FROM PlaylistTrack GROUP BY TrackId
  )
)
ORDER BY t.TrackId;"}

